    for(let i=1;i<12;i++)this.cube(this.content,'Oak floor joint',new vec3(-r.width*50+i*r.width*100/12,.06,0),new vec3(.7,.12,r.depth*100),'floor-joint',new vec4(.77,.73,.63,1));
