      this.softBox(root,'Oak headboard',new vec3(0,h/2,-d/2+3),new vec3(w,h,6),'wood',C.wood);
      for(const x of [-1,1])this.softBox(root,'Linen pillow',new vec3(x*w*.23,h-3,-d*.32),new vec3(w*.4,6,d*.18),'linen',C.linen);
      this.softBox(root,'Sage blanket',new vec3(0,h-5,d*.16),new vec3(w-5,2,d*.59),'sage',C.sage);
